def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v != 0}

    if not any(0 in row for row in grid):
        return [row[:] for row in grid]

    # Extend the repeating diagonal pattern when all three diagonal
    # classes are represented by the clues.
    if h >= 10 and w >= 10:
        by_residue = {}
        for r in range(h):
            for c in range(w):
                v = grid[r][c]
                if v:
                    by_residue[(r + c) % 3] = v
        if len(by_residue) == 3:
            return [[by_residue[(r + c) % 3] for c in range(w)]
                    for r in range(h)]

    # Otherwise, copy the known color along each anti-diagonal.
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] == 0:
                for rr in range(h):
                    cc = r + c - rr
                    if 0 <= cc < w and grid[rr][cc] != 0:
                        out[r][c] = grid[rr][cc]
                        break
    return out
